// job-queue.ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly retries: number;
  private running = 0;
  private pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number, retries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    this.concurrency = concurrency;
    this.retries = retries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are used up. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.attempt(job));
        } catch (err) {
          reject(err);
        } finally {
          this.running--;
          this.next();
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    // ponytail: retries immediately; add backoff if jobs fail on rate limits or flapping dependencies
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.retries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      this.pending.shift()!();
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}
