// orders.js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // connection settings come from the PG* environment variables
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

// The cursor is the sort key of the last row on the page: [created_at, id].
// Both stay strings so neither microseconds nor bigint ids lose precision in JS.
const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, String(row.id)])).toString('base64url');

function decodeCursor(cursor) {
  try {
    const value = JSON.parse(Buffer.from(cursor, 'base64url').toString());
    if (Array.isArray(value) && value.length === 2 && value.every((v) => typeof v === 'string')) {
      return value;
    }
  } catch {}
  return null;
}

// GET /orders?limit=20&cursor=<next_cursor from the previous page>
router.get('/orders', async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = typeof req.query.cursor === 'string' ? decodeCursor(req.query.cursor) : null;
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // Fetch one extra row to learn whether there is a next page.
    const { rows } = await pool.query(
      `SELECT o.*, o.created_at::text AS cursor_ts
         FROM orders o
        ${after ? 'WHERE (o.created_at, o.id) < ($2, $3)' : ''}
        ORDER BY o.created_at DESC, o.id DESC
        LIMIT $1`,
      [limit + 1, ...(after ?? [])],
    );

    const page = rows.slice(0, limit);
    res.json({
      orders: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // 22xxx: a tampered cursor held a value PostgreSQL could not parse
    if (after && err.code?.startsWith('22')) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;

